const DEMO_DESC_HARD = "Корпус из материала «%s» выдерживает удары и не деформируется при погрузке в багажный отсек. Внутри — два отделения с перегородкой на молнии и стяжные ремни, которые удерживают вещи на месте.\n\nЧетыре сдвоенных колеса вращаются на 360°, поэтому чемодан легко катить рядом с собой даже по узкому проходу. Телескопическая ручка фиксируется в нескольких положениях. Кодовый замок TSA позволяет таможенным службам открыть чемодан без повреждений.";
const DEMO_DESC_SOFT = "Тканевый чемодан из водоотталкивающего материала с внешними карманами для документов, ноутбука и мелочей. Молния расширения добавляет около 15%% объёма — удобно, если везёте покупки обратно.\n\nУсиленный каркас держит форму, колёса с бесшумным ходом, телескопическая ручка из алюминия. Вес — всего %s кг.";

function demo_p(array $p): array
{
    $isSoft = str_starts_with($p['material'], 'Ткань');
    $p['desc'] = $p['desc'] ?? ($isSoft ? sprintf(DEMO_DESC_SOFT, num_fmt($p['kg'])) : sprintf(DEMO_DESC_HARD, $p['material']));
    return $p;
}

